import { VoltAgent, VoltAgentWorkflow } from "@voltagent/core";
import { openai } from "@ai-sdk/openai";
import { z } from "zod";

// Initialize the VoltAgent with a system prompt for PII redaction
const agent = new VoltAgent({
  model: openai("gpt-4o"),
  system: "You are a specialized PII Redaction Agent. Your sole responsibility is to identify and redact Personally Identifiable Information (PII) from the input text. PII includes but is not limited to: full names, email addresses, phone numbers, physical addresses, social security numbers, and credit card numbers. Replace each instance of PII with '[REDACTED]'. Do not change any other part of the text.",
});

// Define a VoltAgent workflow for the redaction process
const workflow = new VoltAgentWorkflow({
  agent,
  name: "pii-redactor",
  inputSchema: z.object({
    text: z.string(),
  }),
  outputSchema: z.object({
    redactedText: z.string(),
  }),
});

/**
 * Redacts Personally Identifiable Information (PII) from the given input string.
 * @param input The text containing potential PII.
 * @returns A promise that resolves to the redacted version of the text.
 */
export async function redactPii(input: string): Promise<string> {
  const result = await workflow.run({ text: input });
  return result.redactedText;
}

