import { z } from "zod";

/**
 * PII Redactor Agent
 * Uses a system prompt to identify and redact names and other PII, 
 * and a built-in guardrail for emails and phone numbers.
 */
const redactionAgent = new Agent({
  name: "PII Redactor",
  model: openai("gpt-4o"),
  instructions: `You are a PII Redaction Agent. 
Your task is to identify and redact Personally Identifiable Information (PII) from the given text. 
Specifically, you must redact:
- Full names of individuals
- Email addresses
- Phone numbers
- Physical addresses
- Social Security Numbers or other identification numbers

Replace each instance of detected PII with the exact string '[REDACTED]'. 
Do not change any other part of the text. 
Return the redacted version of the text in the 'redactedText' field.`,
  inputGuardrails: [
    createPIIInputGuardrail({
      replacement: "[REDACTED]",
      maskEmails: true,
      maskPhones: true,
    }),
  ],
});

/**
 * Workflow that orchestrates the redaction process.
 * It takes an input string and uses the redactionAgent to process it.
 */
const redactionWorkflow = createWorkflowChain({
  id: "pii-redaction-workflow",
  name: "PII Redaction Workflow",
  input: z.object({ text: z.string() }),
  result: z.object({ redactedText: z.string() }),
})
  .andAgent(
    ({ data }) => `Please redact PII from the following text: "${data.text}"`,
    redactionAgent,
    {
      schema: z.object({
        redactedText: z.string().describe("The text with PII redacted"),
      }),
    }
  );

/**
 * Redacts Personally Identifiable Information (PII) from the given input string.
 * @param input The text containing potential PII.
 * @returns A promise that resolves to the redacted version of the text.
 */
export async function redactPii(input: string): Promise<string> {
  const result = await redactionWorkflow.run({ text: input });
  return result.result.redactedText;
}

// Register the workflow with a VoltAgent instance for observability and execution
new VoltAgent({
  workflows: { redactionWorkflow },
});

